import { mutationGeneric, queryGeneric } from "convex/server";
import { v } from "convex/values";
import { now, requireGatewaySecret } from "./lib";
import { publicProfileForSession } from "./publicProfile";

export const health = queryGeneric({
  args: { serviceSecret: v.string() },
  handler: async (_ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    return { ok: true };
  },
});

export const account = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string() },
  returns: v.object({ account: v.any(), products: v.array(v.any()), subscriptions: v.array(v.any()) }),
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const [account, products, subscriptions, oauthSession] = await Promise.all([
      ctx.db.query("didAccounts").withIndex("by_did", (q) => q.eq("did", args.did)).unique(),
      ctx.db.query("productMappings").withIndex("by_did_product", (q) => q.eq("did", args.did)).take(100),
      ctx.db.query("subscriptions").withIndex("by_did", (q) => q.eq("did", args.did)).take(100),
      ctx.db.query("oauthSessions").withIndex("by_did", (q) => q.eq("did", args.did)).unique(),
    ]);
    const profile = account?.deletedAt == null && oauthSession
      ? publicProfileForSession(oauthSession.publicProfile, args.did, oauthSession.sessionJson) : null;
    return { account: profile ? { ...account, did: args.did, ...profile } : account, products, subscriptions };
  },
});

export const wallet = queryGeneric({
  args: { serviceSecret: v.string(), did: v.string(), product: v.optional(v.string()) },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    const wallet = await ctx.db.query("wallets").withIndex("by_did", (q) => q.eq("did", args.did)).unique();
    const grants = await ctx.db.query("grantLots").withIndex("by_did_expiry", (q) => q.eq("did", args.did)).take(256);
    const active = grants.filter((lot) => (lot.expiresAt === null || lot.expiresAt > now())
      && (!args.product || lot.productScope === null || lot.productScope === args.product));
    const subscriptions = (await ctx.db.query("subscriptions")
      .withIndex("by_did", (q) => q.eq("did", args.did)).take(100))
      .filter((row) => !args.product || row.product === args.product)
      .map(({ plan, product, status, currentPeriodStart, currentPeriodEnd }) => ({
        plan, product, status, currentPeriodStart, currentPeriodEnd,
      }));
    const availableGrantMicros = active.reduce((sum, lot) => sum + lot.remainingMicros, 0);
    return {
      currency: "USD_MICROS",
      subscriptions,
      balanceMicros: wallet?.balanceMicros ?? 0,
      reservedMicros: wallet?.reservedMicros ?? 0,
      debtMicros: wallet?.debtMicros ?? 0,
