export class ConvexPortalStore implements PortalStore {
  private readonly convex: Pick<ConvexHttpClient, "query" | "mutation">;

  constructor(private readonly config: {
    convexUrl: string;
    portalSecret: string;
    convexClient?: Pick<ConvexHttpClient, "query" | "mutation">;
  }) {
    this.convex = config.convexClient ?? new ConvexHttpClient(config.convexUrl);
  }

  async accessQuery(operation: "listAccounts" | "listCodes" | "listApprovals", actorDid: string, input: Record<string, unknown>): Promise<unknown> {
    return this.convex.query(makeFunctionReference<"query">(`accessManagement:${operation}`), { ...input, ...this.secret, actorDid });
  }

  async accessMutation(operation: "createCode" | "revokeCode" | "directGrant" | "approveWaitlist", actorDid: string, input: Record<string, unknown>): Promise<unknown> {
    return this.convex.mutation(makeFunctionReference<"mutation">(`accessManagement:${operation}`), { ...input, ...this.secret, actorDid });
  }

  async redeemCreditCode(did: string, tokenHash: string): Promise<unknown> {
    return this.convex.mutation(makeFunctionReference<"mutation">("accessManagement:redeemCode"), { ...this.secret, did, tokenHash });
  }

  async listIntegrationApplications(ownerDid: string): Promise<unknown> {
    return this.convex.query(makeFunctionReference<"query">("integrationApplications:list"), { ...this.secret, ownerDid });
  }
  async submitIntegrationApplication(ownerDid: string, application: IntegrationApplication): Promise<unknown> {
    return this.convex.mutation(makeFunctionReference<"mutation">("integrationApplications:submit"), { ...this.secret, ownerDid, ...application });
  }

  async adminAccess(actorDid: string): Promise<{isAdmin:boolean}> {
    return this.convex.query(makeFunctionReference<"query">("integrationAdmin:access"), {...this.secret,actorDid});
  }
  async adminOverview(actorDid: string, range: OverviewRange): Promise<OverviewResult> {
    return this.convex.query(makeFunctionReference<"query">("adminOverview:overview"), { ...range, ...this.secret, actorDid });
  }
  async adminApplications(actorDid: string,cursor: string | null): Promise<unknown> {
    return this.convex.query(makeFunctionReference<"query">("integrationAdmin:applications"), {...this.secret,actorDid,paginationOpts:{cursor,numItems:50}});
  }
  async adminReview(actorDid:string,input:{id:string;expectedUpdatedAt:number;status:"pending"|"approved"|"rejected";note:string;approvedProfileFields?:ProfileField[]}): Promise<unknown> {
    return this.convex.mutation(makeFunctionReference<"mutation">("integrationAdmin:review"), {...this.secret,actorDid,...input});
  }
  async adminHistory(actorDid:string,id:string): Promise<unknown> {
    return this.convex.query(makeFunctionReference<"query">("integrationAdmin:history"),{...this.secret,actorDid,id});
  }

