export const ingestCreemEvent = internalMutationGeneric({
  args: {
    eventId: v.string(),
    eventType: v.string(),
    objectId: v.optional(v.string()),
    createdAt: v.number(),
    payloadHash: v.string(),
    did: v.optional(v.string()),
    customerId: v.optional(v.string()),
    subscriptionId: v.optional(v.string()),
    product: v.optional(v.string()),
    plan: v.optional(v.string()),
    status: v.optional(v.string()),
    currentPeriodStart: v.optional(v.number()),
    currentPeriodEnd: v.optional(v.number()),
    refundId: v.optional(v.string()),
    refundAmountMicros: v.optional(v.number()),
    paymentReference: v.optional(v.string()),
    provider: v.optional(v.literal("paddle")),
    paddleTransaction: v.optional(v.object({ customerId: v.string(), priceId: v.string(), currency: v.string(), principalMinor: v.number(), taxMinor: v.number(), totalMinor: v.number(), itemId: v.string() })),
  },
  handler: async (ctx, args) => {
    if (args.provider === "paddle") await requirePaymentAuthority(ctx, args.did);
    const prior = await ctx.db.query("creemEvents").withIndex("by_event_id", (q) => q.eq("eventId", args.eventId)).unique();
    if (prior) {
      if (prior.payloadHash !== args.payloadHash) throw new Error("EVENT_ID_PAYLOAD_CONFLICT");
      return { duplicate: true, state: prior.processingState };
    }
    const eventId = await ctx.db.insert("creemEvents", {
      eventId: args.eventId,
      eventType: args.eventType,
      objectId: args.objectId,
      createdAt: args.createdAt,
      payloadHash: args.payloadHash,
      processingState: "received",
    });

    if (args.eventType.startsWith("subscription.") || args.eventType === "checkout.completed") {
      if (!args.did || !args.status || !args.plan) throw new Error("BILLING_EVENT_MISSING_IDENTITY");
      const catalog = GRANT_CATALOG[args.plan as GrantCatalogId];
      if (!catalog) throw new Error("UNKNOWN_GRANT_PROGRAM");
      const subscriptions = await ctx.db.query("subscriptions").withIndex("by_did", (q) => q.eq("did", args.did!)).take(100);
      const subscription = args.subscriptionId
        ? subscriptions.find((row) => row.creemSubscriptionId === args.subscriptionId)
        : subscriptions.find((row) => row.plan === args.plan);
      const stale = subscription && args.createdAt < subscription.lastEventCreatedAt;
      if (stale && !(args.provider === "paddle" && args.eventType === "checkout.completed")) {
        await ctx.db.patch(eventId, { processingState: "ignored", processedAt: now() });
        return { duplicate: false, state: "ignored" };
      }
      const value = {
        provider: args.provider ?? subscription?.provider,
        product: args.product ?? subscription?.product ?? catalog.productScope ?? "shared",
        creemCustomerId: args.customerId,
        creemSubscriptionId: args.subscriptionId,
        plan: args.plan ?? subscription?.plan ?? "unknown",
        status: args.status,
        currentPeriodStart: args.currentPeriodStart ?? subscription?.currentPeriodStart,
        currentPeriodEnd: args.currentPeriodEnd ?? subscription?.currentPeriodEnd,
        lastEventCreatedAt: args.createdAt,
        updatedAt: now(),
      };
      if (catalog.cadence === "monthly") {
        // A cancelled subscription can have a null current billing period.
        // Preserve the last known period for lifecycle updates, but never use it
        // to invent a new paid allowance when a funding event omits its period.
        const fundsUsage = ["active", "paid", "trialing", "completed"].includes(args.status);
        if (!args.subscriptionId || (fundsUsage &&
          (args.currentPeriodStart === undefined || args.currentPeriodEnd === undefined))) {
          throw new Error("SUBSCRIPTION_PERIOD_INCOMPLETE");
        }
        if (!stale) {
          if (subscription) await ctx.db.patch(subscription._id, value);
          else await ctx.db.insert("subscriptions", { did: args.did, ...value });
        }
      }
      if (["active", "paid", "trialing", "completed"].includes(args.status) &&
        (args.provider !== "paddle" || args.eventType === "checkout.completed")) {
        const periodStart = args.currentPeriodStart ?? args.createdAt;
        const periodEnd = args.currentPeriodEnd ?? args.createdAt;
        const nominalExpiry =
          catalog.rolloverIntervals === null
            ? null
            : catalog.rolloverIntervals === 0
              ? periodEnd
              : rolloverExpiry(periodStart, periodEnd);
