        // elapsed must still produce a usable grant; throwing here would 400 the
        // webhook and put Creem into a permanent retry loop.
        const expiresAt = usableGrantExpiry(nominalExpiry, Math.max(0, periodEnd - periodStart));
        const grantLotId = await issueGrantFunds(
          ctx,
          {
            did: args.did,
            program: args.plan,
            amountMicros: catalog.amountMicrousd,
            productScope: catalog.productScope,
            expiresAt,
            idempotencyKey:
              catalog.cadence === "once"
                ? `creem-purchase:${args.objectId ?? args.eventId}`
                : `creem-period:${args.subscriptionId}:${args.currentPeriodStart}`,
            reason: `${args.provider === "paddle" ? "Paddle" : "Creem"} ${args.eventType}`,
            deliveryKey: args.provider === "paddle" ? `paddle-event:${args.eventId}` : undefined,
          },
          args.provider ?? "creem",
        );
        if (args.provider === "paddle") {
          if (!args.objectId || !args.product || !args.paddleTransaction) throw new Error("PADDLE_TRANSACTION_INCOMPLETE");
          const value = { transactionId: args.objectId, did: args.did, product: args.product, plan: args.plan,
            subscriptionId: args.subscriptionId, ...args.paddleTransaction, grantLotId };
