            if (Object.entries(value).some(([key, value]) => (priorTransaction as any)[key] !== value)) throw new Error("PADDLE_TRANSACTION_IDENTITY_CONFLICT");
          } else {
            const priorGrantTransaction = await ctx.db.query("paddleTransactions").withIndex("by_grant_lot", (q) => q.eq("grantLotId", grantLotId)).first();
