            await ctx.db.insert("paddleTransactions", { ...value, refundedPrincipalMinor: 0, refundedTaxMinor: 0, refundedGrantMicros: 0, createdAt: args.createdAt });
          }
        }
      }
    } else if (args.eventType === "refund.created") {
      if (!args.refundId || !args.did || args.refundAmountMicros === undefined || !args.paymentReference) {
        throw new Error("REFUND_EVENT_INCOMPLETE");
      }
      assertMicros(args.refundAmountMicros);
      const refund = await ctx.db.query("refunds").withIndex("by_refund_id", (q) => q.eq("refundId", args.refundId!)).unique();
