import { UnisonAuthority } from "./unison-authority";
import { UnisonEncryptedResponses } from "./unison-responses";
import { unisonAchievementStores } from "./unison-achievements";
import { createUnisonProviderStore } from "./unison-store";
import type { ProviderStore } from "./types";
import type { AchievementStore } from "./achievement-routes";
import type { OpenBaoTransit } from "./openbao";

export function nativeProviderSelection(input: {
  env: Readonly<Record<string, string | undefined>>;
  backend: ProviderStore;
  achievements: AchievementStore;
  transit: Pick<OpenBaoTransit, "encrypt" | "decrypt">;
  authority?: UnisonAuthority;
}) {
  const selected = input.env.NOTORGANIC_STORAGE_BACKEND?.trim() || "convex";
  if (selected === "convex") return { store: input.backend, achievements: input.achievements, authority: undefined };
  if (selected !== "unison") throw new Error("NOTORGANIC_STORAGE_BACKEND must be convex or unison");
  const required = (name: string) => {
    const value = input.env[name]?.trim();
    if (!value) throw new Error(`${name} is required for the native provider`);
    return value;
  };
  const connection = { origin: required("NOTORGANIC_UNISON_URL"), serviceKey: required("NOTORGANIC_INTERNAL_SERVICE_KEY") };
  const authority = input.authority ?? new UnisonAuthority({ ...connection, convexUrl: required("CONVEX_URL"), identitySecret: required("CONVEX_GATEWAY_SECRET"), role: "gateway" });
  const native = createUnisonProviderStore({ ...connection, backend: input.backend, responses: new UnisonEncryptedResponses({ ...connection, transit: input.transit }) });
  const refreshed: Partial<ProviderStore> = {
    async reserve(request) { await authority.synchronize(request.accountId, request.product); return native.reserve(request); },
    async getWallet(request) {
      await authority.synchronize(request.accountId, request.product);
      const wallet = await native.getWallet(request) as Record<string, unknown>;
      const account = await input.backend.getAccount({ accountId: request.accountId }) as { subscriptions?: unknown[] };
      const subscriptions = Array.isArray(account?.subscriptions) ? account.subscriptions.flatMap(row => {
        if (!row || typeof row !== "object") return [];
        const value = row as Record<string, unknown>;
        if (request.product && value.product !== request.product) return [];
        const { plan, product, status, currentPeriodStart, currentPeriodEnd } = value;
        return [{ plan, product, status, currentPeriodStart, currentPeriodEnd }];
      }) : [];
      return { ...wallet, subscriptions };
    },
    async listUsage(request) { await authority.synchronize(request.accountId); return native.listUsage(request); },
    async getResponse(request) { await authority.synchronize(request.accountId); return native.getResponse(request); },
    async deleteResponse(request) { await authority.synchronize(request.accountId); return native.deleteResponse(request); },
    async listInputItems(request) { await authority.synchronize(request.accountId); return native.listInputItems(request); },
  };
  const store = new Proxy(native, { get(target, property) {
    const replacement = Reflect.get(refreshed, property);
    if (replacement !== undefined) return replacement;
    const value = Reflect.get(target, property, target);
    return typeof value === "function" ? value.bind(target) : value;
  } });
  return { store, achievements: unisonAchievementStores(authority).gateway, authority };
}

