/** Server-only, read-only access to an operator-configured Resend waitlist. */
export interface AccessWaitlistConfig {
  apiKey?: string;
  segmentId?: string;
  fetcher?: typeof fetch;
}

export interface WaitlistContact {
  id: string;
  email: string;
}

export class AccessWaitlistError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
    this.name = "AccessWaitlistError";
  }
}

export { AccessWaitlistError as WaitlistSourceError };
export type WaitlistConfig = AccessWaitlistConfig;

export function accessWaitlistConfigFromEnv(
  env: Record<string, string | undefined> = process.env,
): AccessWaitlistConfig {
  return {
    apiKey: env.NOTORGANIC_WAITLIST_RESEND_API_KEY?.trim() || env.RESEND_API_KEY?.trim(),
    segmentId: env.NOTORGANIC_WAITLIST_SEGMENT_ID?.trim() || env.KEATING_WAITLIST_SEGMENT_ID?.trim(),
  };
}

const PAGE_SIZE = 50;
const MAX_MEMBERSHIP_PAGES = 20;

function unavailable(): AccessWaitlistError {
  return new AccessWaitlistError("The waitlist is unavailable. Please try again later.", 503);
}

function object(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw unavailable();
  return value as Record<string, unknown>;
}

function validId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= 200
    && value !== "." && value !== ".."
    && value === value.trim() && !/[\u0000-\u001f\u007f]/.test(value);
}

function configured(config: AccessWaitlistConfig) {
  const apiKey = config.apiKey?.trim();
  const segmentId = config.segmentId?.trim();
  if (!apiKey || !validId(segmentId)) {
    throw new AccessWaitlistError("The waitlist has not been configured by the operator.", 503);
  }
  return { apiKey, segmentId, fetcher: config.fetcher ?? fetch };
}

async function request(
  config: ReturnType<typeof configured>,
  path: string,
  after?: string | null,
  paginated = false,
): Promise<unknown> {
  const url = new URL(path, "https://api.resend.com");
  if (paginated) url.searchParams.set("limit", String(PAGE_SIZE));
  if (after != null) {
    if (!validId(after)) throw new AccessWaitlistError("Invalid waitlist cursor.", 404);
    url.searchParams.set("after", after);
  }
  try {
    const response = await config.fetcher(url, {
      method: "GET",
      headers: { authorization: `Bearer ${config.apiKey}`, accept: "application/json" },
      redirect: "error",
      signal: AbortSignal.timeout(8_000),
    });
    if (response.status === 404) throw new AccessWaitlistError("Waitlist contact or segment not found.", 404);
    if (!response.ok) throw unavailable();
    return await response.json();
  } catch (error) {
    if (error instanceof AccessWaitlistError) throw error;
    throw unavailable();
  }
}

function page(value: unknown): { rows: Record<string, unknown>[]; nextCursor: string | null } {
  const body = object(value);
  if (!Array.isArray(body.data) || body.data.length > PAGE_SIZE || typeof body.has_more !== "boolean") {
    throw unavailable();
  }
  const rows = body.data.map(object);
  if (rows.some(row => !validId(row.id))) throw unavailable();
  const lastId = rows.at(-1)?.id;
  if (body.has_more && !validId(lastId)) throw unavailable();
  return { rows, nextCursor: body.has_more ? lastId as string : null };
}

function contact(value: unknown): WaitlistContact & { unsubscribed: boolean } {
  const row = object(value);
  if (!validId(row.id) || typeof row.email !== "string" || row.email.length > 320
    || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(row.email) || typeof row.unsubscribed !== "boolean") {
    throw unavailable();
  }
  return { id: row.id, email: row.email, unsubscribed: row.unsubscribed };
}

export async function listWaitlistContacts(
  config: AccessWaitlistConfig,
  cursor?: string | null,
): Promise<{ data: WaitlistContact[]; nextCursor: string | null }> {
  const source = configured(config);
  const result = page(await request(source, `/segments/${encodeURIComponent(source.segmentId)}/contacts`, cursor, true));
  if (result.nextCursor !== null && result.nextCursor === cursor) throw unavailable();
  return {
    data: result.rows.map(contact).filter(row => !row.unsubscribed).map(({ id, email }) => ({ id, email })),
    nextCursor: result.nextCursor,
  };
}

export async function getWaitlistContact(
  config: AccessWaitlistConfig,
  contactId: string,
): Promise<WaitlistContact & { segmentId: string }> {
  const source = configured(config);
  if (!validId(contactId)) throw new AccessWaitlistError("Waitlist contact not found.", 404);
  const row = contact(await request(source, `/contacts/${encodeURIComponent(contactId)}`));
  if (row.id !== contactId) throw unavailable();
  if (row.unsubscribed) throw new AccessWaitlistError("This contact has unsubscribed from email.", 409);
  let cursor: string | null = null;
  const seen = new Set<string>();
  for (let index = 0; index < MAX_MEMBERSHIP_PAGES; index += 1) {
    const result = page(await request(source, `/contacts/${encodeURIComponent(contactId)}/segments`, cursor, true));
    if (result.rows.some(segment => segment.id === source.segmentId)) {
      return { id: row.id, email: row.email, segmentId: source.segmentId };
    }
    if (result.nextCursor === null) break;
    if (seen.has(result.nextCursor)) throw unavailable();
    seen.add(result.nextCursor);
    cursor = result.nextCursor;
  }
  throw new AccessWaitlistError("This contact is not on the configured waitlist.", 404);
}
