function fixture() {
  let allowed = true;
  const calls: Array<{ operation: string; actorDid: string; input: Record<string, unknown> }> = [];
  const app = createPortalApp({
    config: { publicUrl: "https://id.notorganic.info", secureCookies: true }, oauth: {}, adapter: {},
    store: {
      getPortalSession: async () => ({ did: "did:plc:verified", csrfToken: "csrf" }),
      adminAccess: async () => ({ isAdmin: allowed }),
      accessQuery: async (operation: string, actorDid: string, input: Record<string, unknown>) => {
        calls.push({ operation, actorDid, input });
        return operation === "listApprovals" ? [] : { accounts: [], codes: [], nextCursor: null };
      },
      accessMutation: async (operation: string, actorDid: string, input: Record<string, unknown>) => { calls.push({ operation, actorDid, input }); return { id: "code-record" }; },
      redeemCreditCode: async (actorDid: string, tokenHash: string) => { calls.push({ operation: "redeemCode", actorDid, input: { tokenHash } }); return { amountMicros: 10_000_000 }; },
    },
    waitlist: { apiKey: "server-only", segmentId: "segment", fetcher: (async (url: URL) => {
      if (url.pathname === "/contacts/contact") return Response.json({ id: "contact", email: "person@example.test", unsubscribed: false });
      if (url.pathname.endsWith("/segments")) return Response.json({ data: [{ id: "segment" }], has_more: false });
      return Response.json({ data: [{ id: "contact", email: "person@example.test", unsubscribed: false }], has_more: false });
    }) as unknown as typeof fetch },
  } as unknown as PortalDependencies);
  const headers = { cookie: "nou_portal_session=session", "x-csrf-token": "csrf", "content-type": "application/json" };
  return { app, calls, headers, denyAdmin: () => { allowed = false; } };
}

test("credit administration requires a signed-in administrator and CSRF before any action", async () => {
  const { app, calls, headers, denyAdmin } = fixture();
  expect((await app.request("/api/admin/access/accounts")).status).toBe(401);
  expect((await app.request("/api/admin/access/codes", { method: "POST", headers: { cookie: headers.cookie }, body: "{}" })).status).toBe(403);
  denyAdmin();
  expect((await app.request("/api/admin/access/accounts", { headers })).status).toBe(403);
  expect((await app.request("/api/admin/access/grants", { method: "POST", headers, body: "{}" })).status).toBe(403);
  expect(calls).toHaveLength(0);
});

test("code creation hashes the server-generated secret and ignores browser-supplied authority", async () => {
  const { app, calls, headers } = fixture();
  const response = await app.request("/api/admin/access/codes", { method: "POST", headers, body: JSON.stringify({ label: "Test group", amountMicros: 10_000_000, productScope: "keating", maxUses: 2, expiresAt: Date.now() + 60_000, grantExpiresAt: null, reason: "Testing access", actorDid: "did:plc:spoofed", tokenHash: "browser-selected", portalSecret: "untrusted" }) });
  expect(response.status).toBe(200);
  const body = await response.json();
  expect(body.code).toMatch(/^NOU-[A-Za-z0-9_-]{32}$/);
  expect(calls[0]?.actorDid).toBe("did:plc:verified");
  expect(calls[0]?.input.tokenHash).toBe(createHash("sha256").update(body.code).digest("hex"));
  expect(calls[0]?.input).not.toHaveProperty("actorDid");
  expect(calls[0]?.input).not.toHaveProperty("portalSecret");
  expect(JSON.stringify(calls)).not.toContain(body.code);
  expect(response.headers.get("cache-control")).toBe("private, no-store");
});

test("list/revoke/grant adapters match the backend contract and a credit claim uses the signed-in DID", async () => {
  const { app, calls, headers } = fixture();
  await app.request("/api/admin/access/accounts?cursor=next", { headers });
  expect(calls.at(-1)?.input).toEqual({ paginationOpts: { cursor: "next", numItems: 50 } });
  await app.request("/api/admin/access/codes/code-id/revoke", { method: "POST", headers, body: JSON.stringify({ reason: "Unused code" }) });
  expect(calls.at(-1)?.input).toEqual({ codeId: "code-id", reason: "Unused code" });
  const grant = { did: "did:plc:target", amountMicros: 100_000_000, productScope: null, grantExpiresAt: null, requestId: "stable-retry", reason: "Personal testing" };
  await app.request("/api/admin/access/grants", { method: "POST", headers, body: JSON.stringify({ ...grant, actorDid: "spoofed" }) });
