const PENDING_AUTHORIZATION_COOKIE = "nou_pending_authorization";
const PENDING_AUTHORIZATION_TTL_SECONDS = 10 * 60;

const ACCOUNT_NOTICE_COOKIE = "nou_account_notice";
const DID_PATTERN = /^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/;

/**
 * Per-attempt sign-in state, stored by the OAuth client server-side and returned
 * only from a verified callback. It carries this tab's app continuation so a
 * second tab or app launch cannot redirect another attempt's consent.
 */
interface SignInAttemptState {
  continuation?: string;
  expectedDid?: string;
}

function attemptState(value: string | null | undefined): SignInAttemptState {
  if (!value) return {};
  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    return {
      ...(typeof parsed.continuation === "string" ? { continuation: parsed.continuation } : {}),
      ...(typeof parsed.expectedDid === "string" && DID_PATTERN.test(parsed.expectedDid) ? { expectedDid: parsed.expectedDid } : {}),
    };
  } catch { return {}; }
}

/** A continuation query from the browser, accepted only when it is still a valid public request. */
function validContinuation(value: unknown): string | null {
  if (typeof value !== "string" || value.length > 6000) return null;
  const query = pendingAuthorization(value);
  if (!query) return null;
  return validatePublicAuthorization(Object.fromEntries(new URLSearchParams(query))).ok ? query : null;
}

function pendingAuthorization(value: string): string | null {
  try {
    const decoded = Buffer.from(value, "base64url").toString("utf8");
    return decoded.startsWith("?") && decoded.length <= 4096 ? decoded : null;
  } catch { return null; }
}

function csrfValueMatches(presented: string, expected: string): boolean {
  if (presented.length !== expected.length) return false;
  let difference = 0;
  for (let index = 0; index < presented.length; index += 1) difference |= presented.charCodeAt(index) ^ expected.charCodeAt(index);
  return difference === 0;
}


function listLimit(value: string | undefined): number | undefined {
  if (value === undefined) return undefined;
  const limit = Number(value);
  return Number.isInteger(limit) && limit >= 1 && limit <= 100 ? limit : undefined;
}

/**
 * Gateway calls can fail for reasons the browser has no business seeing (an
 * expired assertion key, a Convex outage). Surface a stable shape and keep the
 * detail server-side.
 */
async function proxied<T>(c: Context, work: () => Promise<T>): Promise<Response> {
  try {
    return c.json((await work()) as never);
  } catch (error) {
    console.error("portal gateway call failed:", error);
    return c.json({ error: { message: "Upstream request failed.", code: "upstream_error" } }, 502);
  }
}

export function createPortalApp(deps: PortalDependencies) {
  const { store, oauth, adapter, config } = deps;
  const pdsUrl = new URL(config.pdsUrl ?? "https://pds.notorganic.info");
  if (pdsUrl.protocol !== "https:" || pdsUrl.username || pdsUrl.password ||
      pdsUrl.pathname !== "/" || pdsUrl.search || pdsUrl.hash) {
    throw new Error("PORTAL_PDS_URL must be an HTTPS origin");
  }
  const app = new Hono<{ Variables: Variables }>();

  // Ported from infra/portal/Caddyfile. connect-src is 'self' only: the browser
  // has no reason to reach the gateway directly any more, and saying so makes a
  // regression that leaks a token to the client fail visibly.
  app.use("*", async (c, next) => {
    await next();
    c.header("X-Content-Type-Options", "nosniff");
    c.header("Referrer-Policy", c.req.path.startsWith("/api/agents") || c.req.path === "/api/knowledge/oauth/callback" ? "no-referrer" : "strict-origin-when-cross-origin");
    c.header(
      "Content-Security-Policy",
      "default-src 'self'; connect-src 'self'; img-src 'self' data:; style-src 'self'; " +
        "script-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'" +
        (c.req.path.startsWith("/account") ? "; form-action 'self'" : ""),
    );
  });

  // Public developer guidance only: no cookies, tokens or customer data are used.
  app.use("/mcp", bodyLimit({maxSize:65536}));
  app.use("/mcp", async (c,next)=>{c.header("Access-Control-Allow-Origin","*");c.header("Access-Control-Allow-Methods","POST, GET, OPTIONS");c.header("Access-Control-Allow-Headers","Content-Type, Accept, MCP-Protocol-Version");c.header("Cache-Control","no-store");return next();});
  app.options("/mcp",c=>c.body(null,204));
  app.all("/mcp",c=>{
    const origin=c.req.header("origin");
    if(origin) {
      let allowed=[new URL(config.publicUrl).origin,"https://docs.notorganic.info","https://notorganic.info"].includes(origin);
      try {const url=new URL(origin);allowed ||= url.origin===origin && url.protocol==="http:" && ["localhost","127.0.0.1","[::1]"].includes(url.hostname);}catch { /* Invalid origins are rejected. */ }
      if(!allowed)return c.json({error:"MCP browser origin is not allowed."},403);
    }
    return handleDeveloperMcp(c.req.raw);
  });
  app.get("/authorization.css", (c) => new Response(authorizationStyles, { headers: { "Content-Type": "text/css; charset=utf-8", "Cache-Control": "no-cache" } }));

  app.get("/healthz", (c) => c.json({ ok: true }));

  app.get("/client-metadata.json", (c) => c.json(clientMetadataDocument(config.publicUrl)));
  app.get("/.well-known/jwks.json", async (c) => c.json(await jwksDocument(config.oauthPrivateJwk)));

