{"label":"limiter","chunk_id":"9082e2","wall_time_seconds":0.000015474,"exit_code":0,"original_token_count":2045,"output":"/**
 * Pre-sign-in account discovery for the entrance screen.
 *
 * Everything here is a public hint, never proof of ownership: the OAuth
 * callback still authenticates the returned DID. Suggestions come from a public
 * AppView, resolution from the same OAuth resolver the sign-in itself uses, so
 * the host shown before navigation is the host the browser will actually reach.
 * Typed queries are never logged or stored.
 */

export interface AccountCandidate {
  did: string;
  handle: string;
  displayName: string | null;
  /** Same-origin, constrained avatar path, or null for initials. */
  avatar: string | null;
}

export interface ResolvedAccount extends AccountCandidate {
  /** Hostname that receives the browser for sign-in (the OAuth issuer). */
  signInHost: string;
  /** Hostname that stores the account, when it differs from the sign-in host. */
  storageHost: string | null;
}

export class AccountNotFoundError extends Error {
  constructor() { super("No account matches that handle."); }
}

export interface AccountDiscovery {
  suggest(query: string, signal?: AbortSignal): Promise<AccountCandidate[]>;
  resolve(identifier: string, signal?: AbortSignal): Promise<ResolvedAccount>;
  avatar(did: string, cid: string, signal?: AbortSignal): Promise<Response | null>;
}

/** The subset of `OAuthClient.oauthResolver` discovery depends on. */
export interface DiscoveryResolver {
  resolveFromIdentity(input: string, options?: { signal?: AbortSignal }): Promise<{
    identityInfo: { did: string; handle: string };
    metadata: { issuer: string };
    pds: URL;
  }>;
}

const DID = /^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/;
const CID = /^[a-z0-9]{20,120}$/;
const AVATAR_URL = /^https:\/\/cdn\.bsky\.app\/img\/avatar(?:_thumbnail)?\/plain\/(did:[a-z0-9]+:[A-Za-z0-9._:%-]+)\/([a-z0-9]{20,120})@jpeg$/;
const MAX_AVATAR_BYTES = 256_000;
const SUGGESTION_LIMIT = 6;
const TIMEOUT_MS = 2_500;

/** Normalizes a typeahead query, or null when it is too short or unsafe to forward. */
export function suggestionQuery(input: unknown): string | null {
  if (typeof input !== "string") return null;
  const query = input.trim().replace(/^@/, "").toLowerCase();
  if (query.length < 2 || query.length > 64 || !/^[a-z0-9][a-z0-9._ -]*$/.test(query)) return null;
  return query;
}

function text(value: unknown, max = 128): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.replace(/[\u0000-\u001f\u007f]/g, "").trim();
  return trimmed ? trimmed.slice(0, max) : null;
}

/** Maps an AppView CDN avatar onto the portal's constrained proxy path. */
export function proxiedAvatar(url: unknown): string | null {
  if (typeof url !== "string") return null;
  const match = AVATAR_URL.exec(url);
  if (!match) return null;
  return `/api/auth/avatar?${new URLSearchParams({ did: match[1]!, cid: match[2]! })}`;
}

function candidate(actor: unknown): AccountCandidate | null {
  if (!actor || typeof actor !== "object") return null;
  const value = actor as Record<string, unknown>;
  const did = typeof value.did === "string" && DID.test(value.did) ? value.did : null;
  const handle = text(value.handle, 253)?.toLowerCase() ?? null;
  if (!did || !handle || handle === "handle.invalid") return null;
  return { did, handle, displayName: text(value.displayName), avatar: proxiedAvatar(value.avatar) };
}

function timeout(signal?: AbortSignal): AbortSignal {
  return signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS);
}

export function createAccountDiscovery(options: {
  resolver: DiscoveryResolver;
  appViewUrl?: string;
  fetch?: typeof fetch;
}): AccountDiscovery {
  const appView = new URL(options.appViewUrl ?? "https://public.api.bsky.app");
  const request = options.fetch ?? fetch;

  const xrpc = async (method: string, params: Record<string, string>, signal?: AbortSignal) => {
    const response = await request(new URL(`/xrpc/${method}?${new URLSearchParams(params)}`, appView), {
      signal: timeout(signal), redirect: "error", headers: { accept: "application/json" },
    });
    return response.ok ? await response.json() as Record<string, unknown> : null;
  };

  /** Display name from the account's own PDS, for accounts no AppView indexes yet. */
  const pdsDisplayName = async (pds: URL, did: string, signal?: AbortSignal) => {
    const response = await request(new URL(`/xrpc/com.atproto.repo.getRecord?${new URLSearchParams({ repo: did, collection: "app.bsky.actor.profile", rkey: "self" })}`, pds), {
      signal: timeout(signal), redirect: "error", headers: { accept: "application/json" },
    });
    if (!response.ok) return null;
    const record = await response.json() as { value?: { displayName?: unknown } };
    return text(record.value?.displayName);
  };

  return {
    async suggest(query, signal) {
      const body = await xrpc("app.bsky.actor.searchActorsTypeahead", { q: query, limit: String(SUGGESTION_LIMIT) }, signal);
      const actors = Array.isArray(body?.actors) ? body.actors : [];
      return actors.map(candidate).filter((value): value is AccountCandidate => value !== null).slice(0, SUGGESTION_LIMIT);
    },

    async resolve(identifier, signal) {
      let resolved: Awaited<ReturnType<DiscoveryResolver["resolveFromIdentity"]>>;
      try {
        resolved = await options.resolver.resolveFromIdentity(identifier, { signal: timeout(signal) });
      } catch (error) {
        if (signal?.aborted) throw error;
        throw new AccountNotFoundError();
      }
      const { did, handle } = resolved.identityInfo;
      const signInHost = new URL(resolved.metadata.issuer).hostname;
      const storageHost = resolved.pds.hostname === signInHost ? null : resolved.pds.hostname;
      // Profile data is decoration. A missing or slow profile never blocks sign-in.
      const profile = await xrpc("app.bsky.actor.getProfile", { actor: did }, signal).catch(() => null);
      const fromAppView = profile && profile.did === did ? candidate(profile) : null;
      const displayName = fromAppView?.displayName ?? await pdsDisplayName(resolved.pds, did, signal).catch(() => null);
      return {
        did,
        handle: handle === "handle.invalid" ? did : handle.toLowerCase(),
        displayName,
        avatar: fromAppView?.avatar ?? null,
        signInHost,
        storageHost,
      };
    },

    async avatar(did, cid, signal) {
      if (!DID.test(did) || !CID.test(cid)) return null;
      const response = await request(`https://cdn.bsky.app/img/avatar_thumbnail/plain/${did}/${cid}@jpeg`, {
        signal: timeout(signal), redirect: "error",
      });
      if (!response.ok || response.headers.get("content-type")?.split(";")[0]?.trim() !== "image/jpeg" || !response.body) return null;
      const reader = response.body.getReader();
      const chunks: Uint8Array[] = [];
      let size = 0;
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > MAX_AVATAR_BYTES) { await reader.cancel(); return null; }
        chunks.push(value);
      }
      const body = new Uint8Array(size);
      let offset = 0;
      for (const chunk of chunks) { body.set(chunk, offset); offset += chunk.byteLength; }
      return new Response(body, { headers: {
        "Content-Type": "image/jpeg",
        "Cache-Control": "public, max-age=3600",
        "X-Content-Type-Options": "nosniff",
      } });
    },
  };
}

/**
 * Small fixed-window limiter for anonymous discovery. Keyed by the first
 * forwarded address; the key is held only for the window and never logged.
 */
export function createDiscoveryLimiter(limit = 60, windowMs = 60_000) {
  const windows = new Map<string, { count: number; resetAt: number }>();
  return (key: string, now = Date.now()): boolean => {
    if (windows.size > 10_000) for (const [entry, value] of windows) if (value.resetAt <= now) windows.delete(entry);
    const current = windows.get(key);
    if (!current || current.resetAt <= now) {
      windows.set(key, { count: 1, resetAt: now + windowMs });
      return true;
    }
    current.count += 1;
    return current.count <= limit;
  };
}
"}

