import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";
import { accessApi, creditAmount, type CreditCode } from "../access-api";
import { Empty, productLabel, timestamp, usdRounded } from "../ui";
import type { CreditProductScope } from "../../access-management";

type Scope = CreditProductScope;
type Page<T> = { rows: T[]; cursor: string | null };
const products = ["keating", "twyne", "stich", "interleave"];

function ProductScope({ value, onChange }: { value: Scope; onChange: (value: Scope) => void }) {
  return <label>Usable in<select value={value ?? ""} onChange={event => onChange((event.target.value || null) as Scope)}><option value="">All products</option>{products.map(product => <option value={product} key={product}>{productLabel(product)}</option>)}</select></label>;
}

function usePages<T>(load: (cursor?: string | null) => Promise<Page<T>>) {
  const [rows, setRows] = useState<T[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [busy, setBusy] = useState(true);
  const [error, setError] = useState("");
  const generation = useRef(0);
  const loadPage = useCallback(async (next?: string | null) => {
    const version = ++generation.current;
    setBusy(true); setError("");
    try {
      const page = await load(next);
