      const result = await accessApi.createCode({ label: label.trim(), amountMicros, productScope: scope, maxUses: uses, expiresAt, grantExpiresAt: null, reason: reason.trim() });
      setGenerated(result.code);
      void page.refresh();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not create this code."); }
    finally { setBusy(false); }
  }
  return <div className="access-layout"><section className="panel"><p className="eyebrow">Invitations & gifts</p><h3>Create a credit code</h3><p>Give one person or a group a fixed amount of usage credit.</p>
    <form onSubmit={event => void create(event)}><fieldset disabled={busy}>
      <label>Label<input value={label} onChange={event => setLabel(event.target.value)} required maxLength={100} placeholder="For example: October testers" /></label>
      <div className="access-form-pair"><label>Credit per person (USD)<input type="number" min="0.01" max="1000" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} required /></label><label>Maximum uses<input type="number" min="1" max="1000" step="1" value={maxUses} onChange={event => setMaxUses(event.target.value)} required /></label></div>
      <ProductScope value={scope} onChange={setScope} />
      <label>Redeem by<input type="date" value={expires} onChange={event => setExpires(event.target.value)} required /></label>
      <p className="hint">Each account can redeem the code once. Redeemed credit does not expire.</p>
      <label>Admin note<textarea value={reason} onChange={event => setReason(event.target.value)} required minLength={3} maxLength={500} rows={3} placeholder="Why are you issuing this credit?" /></label>
      <button className="primary" disabled={!label.trim() || reason.trim().length < 3}>{busy ? "Creating code…" : "Generate code"}</button>
    </fieldset>{error && <p role="alert">{error}</p>}</form>
    {generated && <GeneratedCode key={generated} code={generated} label="Your new credit code" />}
  </section><section className="panel"><h3>Credit codes</h3><LoadState busy={page.busy} error={page.error} retry={page.refresh} /><ul className="access-list">{page.rows.map(code => <CodeRow key={code.id} code={code} onRevoked={page.refresh} />)}</ul>{!page.busy && !page.error && !page.rows.length && <Empty>No codes yet. Generate one to invite a tester or share credit.</Empty>}{page.cursor && <button disabled={page.busy} onClick={() => void page.more()}>Load more codes</button>}</section></div>;
}

function Waitlist() {
  const page = usePages(waitlistPage);
  const [amount, setAmount] = useState("10");
  const [scope, setScope] = useState<Scope>(null);
  const [reason, setReason] = useState("");
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState("");
  const [generated, setGenerated] = useState<{ code: string; email: string } | null>(null);
  async function approve(id: string, email: string) {
    if (busy) return;
    setBusy(id); setError("");
    try {
      const result = await accessApi.approveWaitlist(id, { amountMicros: creditAmount(amount), productScope: scope, reason: reason.trim() });
      setGenerated({ code: result.code, email });
      void page.refresh();
    } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not approve this person."); }
    finally { setBusy(null); }
  }
  return <div className="access-layout"><section className="panel"><p className="eyebrow">Make room</p><h3>Welcome people from the waitlist</h3><p>Approval creates a personal credit code. Copy it and send it to the person yourself.</p><fieldset disabled={busy !== null}>
    <label>Welcome credit (USD)<input type="number" min="0.01" max="1000" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} /></label><ProductScope value={scope} onChange={setScope} /><label>Approval note<textarea value={reason} onChange={event => setReason(event.target.value)} minLength={3} maxLength={500} rows={3} placeholder="For example: opening access to the next group" /></label>
  </fieldset>{error && <p role="alert">{error}</p>}{generated && <GeneratedCode key={generated.code} code={generated.code} label={`Approved: ${generated.email}`} />}</section>
    <section className="panel"><h3>Waitlist</h3><LoadState busy={page.busy} error={page.error} retry={page.refresh} /><ul className="access-list">{page.rows.map(person => <li className="access-waitlist-row" key={person.id}><div><strong>{person.email}</strong><small>{person.status === "approved" ? `Approved${person.approvedAt ? ` ${timestamp(person.approvedAt)}` : ""}` : "Waiting for access"}</small></div>{person.status === "pending" && <button className="primary" disabled={busy !== null || reason.trim().length < 3} onClick={() => void approve(person.id, person.email)}>{busy === person.id ? "Approving…" : "Approve & create code"}</button>}</li>)}</ul>{!page.busy && !page.error && !page.rows.length && <Empty>No one is waiting for access.</Empty>}{page.cursor && <button disabled={page.busy} onClick={() => void page.more()}>Load more people</button>}</section>
  </div>;
}

export function AccessAdmin({ allowed }: { allowed: boolean }) {
  const [tab, setTab] = useState<"accounts" | "codes" | "waitlist">("accounts");
  const [visited, setVisited] = useState({ accounts: true, codes: false, waitlist: false });
  if (!allowed) return <section className="panel"><h2>Admin access required</h2><p>Account credit, invitation codes and waitlist approvals are available to authorized administrators.</p></section>;
  return <section className="access-admin"><header className="access-heading"><p className="eyebrow">Administration</p><h2>People & credit</h2><p>Find an account, give someone more room to explore, or welcome the next group.</p></header><nav className="access-tabs" aria-label="Account administration">{([["accounts", "Accounts"], ["codes", "Credit codes"], ["waitlist", "Waitlist"]] as const).map(([value, label]) => <button key={value} aria-pressed={tab === value} onClick={() => { setTab(value); setVisited(old => ({ ...old, [value]: true })); }}>{label}</button>)}</nav><div hidden={tab !== "accounts"}><Accounts /></div>{visited.codes && <div hidden={tab !== "codes"}><CreditCodes /></div>}{visited.waitlist && <div hidden={tab !== "waitlist"}><Waitlist /></div>}</section>;
}
"}

