  ctx: GenericMutationCtx<any>,
  actor: string,
  action: string,
  target: string,
  reason: string,
  metadata?: unknown,
): Promise<void> {
  // Reconciliation may still audit a deleted financial target. Sanitize the
  // record instead of rejecting the already authorized financial operation.
  let metadataJson = metadata === undefined ? undefined : JSON.stringify(metadata);
  const pattern = /did:[a-z][a-z0-9]*:[A-Za-z0-9._:%-]+/g;
  const references = new Set<string>([actor, target].filter(value => value.startsWith("did:")));
  for (const value of [actor, target, reason, metadataJson ?? ""]) for (const match of decodeAuditReferences(value).matchAll(pattern)) {
    references.add(match[0]);
    if (match[0].endsWith(".")) references.add(match[0].replace(/\.+$/, ""));
