import { afterAll, beforeAll, expect, test } from "bun:test";
import { convexTest } from "convex-test";
import { makeFunctionReference } from "convex/server";
import schema from "../convex/schema";

const modules = {
  "../convex/_generated/server.js": () => import("../convex/_generated/server.js"),
  "../convex/purchaseWaitlist.ts": () => import("../convex/purchaseWaitlist"),
};
const join = makeFunctionReference<"mutation">("purchaseWaitlist:join");
const list = makeFunctionReference<"query">("purchaseWaitlist:list");
const portalSecret = "waitlist-test-secret", actorDid = "did:plc:admin";
const prior = { portal: process.env.CONVEX_PORTAL_SECRET, admin: process.env.NOTORGANIC_ADMIN_DIDS };
beforeAll(() => { process.env.CONVEX_PORTAL_SECRET = portalSecret; process.env.NOTORGANIC_ADMIN_DIDS = actorDid; });
afterAll(() => {
  for (const [key, value] of [["CONVEX_PORTAL_SECRET", prior.portal], ["NOTORGANIC_ADMIN_DIDS", prior.admin]] as const) {
    if (value === undefined) delete process.env[key]; else process.env[key] = value;
  }
});
const input = { portalSecret, email: "writer@example.test", product: "twyne", intent: "credits", offerId: "twyne_credit_10" };
const admin = { portalSecret, actorDid, paginationOpts: { numItems: 50, cursor: null } };

test("retrying an interest does not duplicate it; different packs and subscription interest remain distinct", async () => {
  const t = convexTest(schema, modules);
  await Promise.all([t.mutation(join, input), t.mutation(join, { ...input, email: "Writer@Example.test" })]);
  await t.mutation(join, { ...input, offerId: "twyne_credit_25" });
  await t.mutation(join, { ...input, intent: "subscription", offerId: "twyne_pro_v2" });
  const result = await t.query(list, admin);
  expect(result.page).toHaveLength(3);
  expect(result.page.map((row: any) => row.offerId).sort()).toEqual(["twyne_credit_10", "twyne_credit_25", "twyne_pro_v2"]);
  expect(await t.run(ctx => ctx.db.query("subscriptions").collect())).toHaveLength(0);
  expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toHaveLength(0);
});

test("rejects forged authority, cross-product offers and invalid email without exposing the queue", async () => {
  const t = convexTest(schema, modules);
  for (const patch of [{ portalSecret: "wrong" }, { offerId: "keating_pack_10" }, { intent: "setup" }, { email: "invalid" }]) {
    await expect(t.mutation(join, { ...input, ...patch })).rejects.toThrow();
  }
  await t.mutation(join, input);
  await expect(t.query(list, { ...admin, actorDid: "did:plc:visitor" })).rejects.toThrow("ADMIN_ACCESS_REQUIRED");
  await expect(t.query(list, { ...admin, portalSecret: "wrong" })).rejects.toThrow("FORBIDDEN");
  expect((await t.query(list, admin)).page).toHaveLength(1);
});

import { expect, test } from "bun:test";
import { createPortalApp, type PortalDependencies } from "./routes";

function fixture(fail = false) {
  const entries: unknown[] = [];
  const app = createPortalApp({
    config: { publicUrl: "https://id.notorganic.info", secureCookies: true }, oauth: {}, adapter: {},
    store: { joinPurchaseWaitlist: async (input: unknown) => { if (fail) throw new Error("private upstream details"); entries.push(input); } },
  } as unknown as PortalDependencies);
  return { app, entries };
}

async function form(app: ReturnType<typeof createPortalApp>, query = "product=twyne&intent=credits&offerId=twyne_credit_25") {
  const response = await app.request(`/waitlist?${query}`);
  const text = await response.text();
  const csrf = text.match(/name="csrf" value="([^"]+)"/)?.[1];
  return { response, text, csrf: csrf!, cookie: response.headers.get("set-cookie")!.split(";")[0]! };
}

test("public form preserves purchase intent without requiring an account or collecting payment", async () => {
  const { app, entries } = fixture();
  const { response, text } = await form(app);
  expect(response.status).toBe(200);
  expect(text).toContain("$25 AI credit");
  expect(text).toContain('name="offerId" value="twyne_credit_25"');
  expect(text).not.toContain("twyne credit 25");
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(entries).toHaveLength(0);
  expect((await app.request("/waitlist?product=twyne&intent=credits&offerId=keating_pack_10")).status).toBe(400);
});

test("submission requires its same-origin form and records only validated fields", async () => {
  const { app, entries } = fixture();
  const { csrf, cookie } = await form(app);
  const body = new URLSearchParams({ csrf, product: "twyne", intent: "credits", offerId: "twyne_credit_25", email: "Writer@Example.test", actorDid: "did:plc:spoofed" });
  const send = (origin: string, cookieValue = cookie) => app.request("/waitlist", { method: "POST", headers: { origin, cookie: cookieValue, "content-type": "application/x-www-form-urlencoded" }, body });
  expect((await send("https://elsewhere.example")).status).toBe(403);
  expect((await send("https://id.notorganic.info", "")).status).toBe(403);
  expect(entries).toHaveLength(0);
  const response = await send("https://id.notorganic.info");
  expect(response.status).toBe(200);
  expect(await response.text()).toContain("Your request for AI credits is saved");
  expect(entries).toEqual([{ product: "twyne", intent: "credits", offerId: "twyne_credit_25", email: "writer@example.test" }]);
});

test("invalid email and storage failure never claim a saved request", async () => {
  for (const fail of [false, true]) {
    const { app, entries } = fixture(fail);
    const { csrf, cookie } = await form(app);
    const response = await app.request("/waitlist", { method: "POST", headers: { origin: "https://id.notorganic.info", cookie, "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ csrf, product: "twyne", intent: "subscription", offerId: "twyne_pro_v2", email: fail ? "writer@example.test" : "invalid" }) });
    expect(response.status).toBe(fail ? 503 : 400);
    const text = await response.text();
    expect(text).not.toContain("is saved");
    expect(text).not.toContain("private upstream details");
    expect(entries).toHaveLength(0);
  }
});

test("purchase interest is visible only to a signed-in administrator", async () => {
  let reads = 0;
  let isAdmin = false;
  const app = createPortalApp({ config: { publicUrl: "https://id.notorganic.info", secureCookies: true }, oauth: {}, adapter: {}, store: {
    getPortalSession: async () => ({ did: "did:plc:admin", csrfToken: "csrf" }), adminAccess: async () => ({ isAdmin }),
    listPurchaseWaitlist: async (actorDid: string) => { expect(actorDid).toBe("did:plc:admin"); reads++; return { page: [], isDone: true, continueCursor: "" }; },
  } } as unknown as PortalDependencies);
  expect((await app.request("/api/admin/access/requests")).status).toBe(401);
  const headers = { cookie: "nou_portal_session=session" };
  expect((await app.request("/api/admin/access/requests", { headers })).status).toBe(403);
  expect(reads).toBe(0);
  isAdmin = true;
  expect((await app.request("/api/admin/access/requests", { headers })).status).toBe(200);
  expect(reads).toBe(1);
});

