import { socialHead } from "../lib/social";
import { useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { createFileRoute, Link } from "@tanstack/react-router";
import { LCARSButton, LCARSPanel, LCARSSeparator } from "@stich/ui";
import {
  NotOrganicPublicClient,
  publicClientConfig,
  type NotOrganicProviderSession,
} from "../lib/notorganic-public-client";
import {
  STICH_CREDIT_PACKS,
  STICH_SUBSCRIPTION_PLANS,
  isPublicCheckoutConfigured,
  pricingAvailability,
  isSubscriptionCheckoutConfigured,
  walletSpendableMicros,
} from "../lib/pricing";

export const Route = createFileRoute("/pricing")({
  component: PricingPage,
  head: () => socialHead({
    title: "Pricing · Stich",
    description: "Stich is free with your own server. Managed mail hosting is planned and not yet available.",
    path: "/pricing",
  }),
});

interface WalletView {
  balanceMicros: number;
  availableGrantMicros: number;
  reservedMicros: number;
  debtMicros: number;
  hostedInferenceBlocked: boolean;
}

const primaryLink =
  "inline-flex min-h-11 items-center rounded-l-[6px] rounded-r-[24px] bg-lcars-orange px-6 py-2.5 font-display text-sm font-bold uppercase tracking-wider text-space-black transition-colors hover:bg-lcars-peach focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-lcars-cream/70";

function dollars(micros: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(micros / 1_000_000);
}

function PricingPage() {
  const subscriptionsConfigured = isSubscriptionCheckoutConfigured(import.meta.env);
  const checkoutConfigured = isPublicCheckoutConfigured(import.meta.env);
  const clientConfig = checkoutConfigured ? publicClientConfig() : null;
  const client = useMemo(
    () => (clientConfig ? new NotOrganicPublicClient(clientConfig) : null),
    [clientConfig?.issuer, clientConfig?.authorizationUrl, clientConfig?.clientId],
  );
  const [session, setSession] = useState<NotOrganicProviderSession | null>(null);
  const [wallet, setWallet] = useState<WalletView | null>(null);
  const [busyCheckout, setBusyCheckout] = useState<string | null>(null);
  const [walletBusy, setWalletBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const availability = pricingAvailability(checkoutConfigured, Boolean(session));

  useEffect(() => {
    if (!client) return;
    setSession(client.getSession());
  }, [client]);

  const refreshWallet = async () => {
    if (!client) return;
    setWalletBusy(true);
    try {
      const response = await client.request("/v1/wallet");
      const next = (await response.json().catch(() => null)) as WalletView | null;
      if (
        !response.ok ||
        !next ||
        ![next.balanceMicros, next.availableGrantMicros, next.reservedMicros, next.debtMicros].every(
          Number.isSafeInteger,
        )
      ) {
        throw new Error("Not Organic returned an invalid wallet response.");
      }
      setWallet(next);
      setMessage(null);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not read the wallet.");
    } finally {
      setWalletBusy(false);
    }
  };

  useEffect(() => {
    if (session) void refreshWallet();
    // A new authorization remounts this route. Polling a money surface is not
    // useful, so refresh only when the browser session changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session]);

  const connect = async () => {
    if (!client) return;
    try {
      setMessage(null);
      window.location.assign(await client.authorizationUrl());
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Could not start the Not Organic connection.",
      );
    }
  };

  const buy = async (selection: { id: string; kind: "plan" | "pack" }) => {
    if (!client || (selection.kind === "plan" && !subscriptionsConfigured)) return;
    if (!session) {
      await connect();
      return;
    }
    setBusyCheckout(selection.id);
    setMessage(null);
    try {
      const response = await client.request("/v1/billing/checkout", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          [selection.kind === "plan" ? "plan_id" : "pack_id"]: selection.id,

	if (action === "loading" || action === "unavailable") return;
	// Keep the established event name stable: selecting a pack is purchase
	// intent, not a completed checkout. The availability property makes that
	// distinction explicit without breaking historical funnels.
	posthog?.capture("pricing_pack_selected", {
		pack_id: pack.id,
		price_usd: pack.priceUsd,
		availability,
		pricing_cta_variant: pricingVariant,
	});
	if (!publicClient || action === "waitlist") {
		promptCreditWaitlist(pack.id, pricingVariant);
		return;
	}
	checkoutPending.current = true;
	setPendingPack(pack.id);
	try {
		setBillingError(null);
		if (!connected) {
			setProviderSession(null);
			window.location.assign(await publicClient.authorizationUrl(`/pricing?pack=${pack.id}`));
			return;
		}
		const result = await createNotOrganicCheckout(pack.id, `${window.location.origin}/pricing?checkout=returned`);
		const checkoutUrl = typeof result?.url === "string" ? result.url : typeof result?.checkout_url === "string" ? result.checkout_url : null;
		if (!checkoutUrl || new URL(checkoutUrl).protocol !== "https:") throw new Error("Checkout unavailable");
		window.location.assign(checkoutUrl);
	} catch {
		setBillingError(providerSession
			? "We couldn’t open checkout. Your selection is still here; please try again."
			: "We couldn’t open account sign-in. Please try choosing your pack again.");
	} finally {
		checkoutPending.current = false;
		setPendingPack(null);
	}
};

const plansEnabled = checkoutConfigured && subscriptionCheckoutEnabled(import.meta.env);
const planAvailable = subscriptionAvailable(wallet, plansEnabled);
const buySubscription = async () => {
	if (checkoutPending.current || !plansEnabled || !publicClient) return;
	checkoutPending.current = true;
	setPendingPack(KEATING_PERSONAL_PLAN.id);
	try {
		setBillingError(null);
		if (!readPricingSession(publicClient)) {
			setProviderSession(null);
			window.location.assign(await publicClient.authorizationUrl("/pricing?plan=keating_personal_v2"));
			return;
		}
		if (!planAvailable) throw new Error("Subscription checkout is not available yet.");
		const result = await createNotOrganicSubscriptionCheckout(KEATING_PERSONAL_PLAN.id, `${window.location.origin}/pricing?checkout=returned`);
		const url = result.url ?? result.checkout_url;
		if (!url || new URL(url).protocol !== "https:") throw new Error("Checkout unavailable");
		window.location.assign(url);
	} catch {
		setBillingError("We couldn’t open your subscription checkout. Your current plan and balance have not changed.");
	} finally {
		checkoutPending.current = false;
		setPendingPack(null);
	}

