function initialView(): View {
  const params = new URLSearchParams(location.search);
  const requested = params.get("view");
  try {
    if (requested === "knowledge") rememberKnowledgeHandoff(params, sessionStorage);
    const claim = params.get("claim_attempt_token");
    if (claim && /^cla_[A-Za-z0-9_-]{43}$/.test(claim)) {
      sessionStorage.setItem("notorganic-agent-claim", claim);
      params.delete("claim_attempt_token");
      history.replaceState(null, "", `${location.pathname}?${params}`);
    }
    const entries = ["integrations", "admin", "knowledge", "agents", "achievements", "profile"];
    if (requested && entries.includes(requested)) sessionStorage.setItem("notorganic-entry-view", requested);
    const entry = requested && entries.includes(requested) ? requested : sessionStorage.getItem("notorganic-entry-view");
    if (entry && entries.includes(entry)) return entry as View;
  } catch { /* Storage can be unavailable; direct links still work. */ }
  return requested === "profile" ? "profile" : requested === "achievements" ? "achievements" : requested === "agents" ? "agents" : requested === "knowledge" ? "knowledge" : requested === "admin" ? "admin" : requested === "integrations" ? "integrations" : "settings";
}
